from collections import defaultdict, deque

def read_ints():
    return list(map(int, input().split()))

# Read input
N, M = read_ints()
E = read_ints()
graph = defaultdict(list)
indegree = [0] * N

# Read dependencies
for _ in range(M):
    T1, T2 = read_ints()
    graph[T2].append(T1)  # Reverse the direction of edges for topological sort
    indegree[T1] += 1

# Topological sort using Kahn's algorithm
queue = deque()
for i in range(N):
    if indegree[i] == 0:
        queue.append(i)

order = []
while queue:
    node = queue.popleft()
    order.append(node)
    for neighbor in graph[node]:
        indegree[neighbor] -= 1
        if indegree[neighbor] == 0:
            queue.append(neighbor)

# Calculate the minimal number of coprocessor calls
coprocessor_calls = 0
tasks_on_coprocessor = [i for i in range(N) if E[i] == 1]

visited = [False] * N
for task in tasks_on_coprocessor:
    if not visited[task]:
        coprocessor_calls += 1
        queue = deque([task])
        while queue:
            node = queue.popleft()
            if not visited[node]:
                visited[node] = True
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        queue.append(neighbor)

print(coprocessor_calls)
